		new("medieval_buddhist_patched_kasaya", "kasaya", "a patched cotton kasaya", BuildDocumentedClothingFullDescription("a patched cotton kasaya", "kasaya", "cotton", ["Holdable", "Wear_Mantle", "Destroyable_Clothing", "Insulation_Moderate", "Armour_HeavyClothing"], ItemQuality.Standard), SizeCategory.Normal, ItemQuality.Standard, 320.0, 24.0m, true, "cotton", ["Market / Clothing / Standard Clothing", "Functions / Worn Items / Bodywear"], ["Holdable", "Wear_Mantle", "Destroyable_Clothing", "Insulation_Moderate", "Armour_HeavyClothing"], "Early Modern admission of an exact Medieval clothing definition."),
		new("medieval_buddhist_travelling_mantle", "mantle", "a dark wool monastic travelling mantle", BuildDocumentedClothingFullDescription("a dark wool monastic travelling mantle", "mantle", "wool", ["Holdable", "Wear_Cloak_(Open)", "Destroyable_Clothing", "Insulation_Moderate", "Armour_HeavyClothing"], ItemQuality.Standard), SizeCategory.Normal, ItemQuality.Standard, 760.0, 24.0m, true, "wool", ["Market / Clothing / Standard Clothing", "Functions / Worn Items / Bodywear"], ["Holdable", "Wear_Cloak_(Open)", "Destroyable_Clothing", "Insulation_Moderate", "Armour_HeavyClothing"], "Early Modern admission of an exact Medieval clothing definition."),
		new("medieval_daoist_cloud_sleeved_robe", "robe", "a fine $colour cloud-sleeved robe", "This fine $colour cloud-sleeved robe is a silk ritual garment with broad sleeves and a loose cross-collar body. The sleeves spread widely from the arm, making the $colour silk fall in soft ceremonial folds. Its shape is more expansive than an ordinary robe, giving the garment a deliberate temple-formal presence.", SizeCategory.Normal, ItemQuality.Good, 680.0, 130.0m, true, "silk", ["Market / Clothing / Luxury Clothing", "Functions / Worn Items / Bodywear"], ["Holdable", "Wear_Robe", "Destroyable_Clothing", "Insulation_Moderate", "Armour_LightClothing", "Variable_FineColour"], "Early Modern admission of an exact Medieval clothing definition."),
		new("medieval_daoist_cross_collar_robe", "robe", "a $colour cross-collared cotton robe", "The front panels of this $colour cotton robe overlap beneath a long cross-collar. Ties hold the wrapped closure against a straight, loosely cut body. Long sleeves retain a plain outline, without the broad extensions of a cloud-sleeved overrobe. The cotton is smooth and closely woven, and narrow seams and hems provide its only visible finishing.", SizeCategory.Normal, ItemQuality.Standard, 520.0, 24.0m, true, "cotton", ["Market / Clothing / Standard Clothing", "Functions / Worn Items / Bodywear"], ["Holdable", "Variable_Colour", "Wear_Robe_Layer_0_5_NonBulky", "Destroyable_Clothing", "Insulation_Moderate", "Armour_LightClothing"], "Early Modern admission of an exact Medieval clothing definition."),
		new("medieval_daoist_ritual_cap", "cap", "a $colour cloth ritual cap", "Stiffened panels of $colour cotton give this cap a compact, angular outline. Small seams join the panels without rounding away their distinct edges. The lower opening is neatly finished and sits beneath a crown that holds its shape without a projecting brim. Its surface is plain, with the close weave and slight changes of plane visible instead of embroidered ornament.", SizeCategory.Small, ItemQuality.Standard, 90.0, 12.0m, true, "cotton", ["Market / Clothing / Standard Clothing", "Functions / Worn Items / Headwear"], ["Holdable", "Variable_Colour", "Wear_Hat", "Destroyable_Clothing", "Insulation_Minor", "Armour_LightClothing"], "Early Modern admission of an exact Medieval clothing definition."),
		new("medieval_eastern_black_klobuk", "klobuk", "a black veiled klobuk", BuildDocumentedClothingFullDescription("a black veiled klobuk", "klobuk", "wool", ["Holdable", "Wear_Hat", "Destroyable_Clothing", "Insulation_Moderate", "Armour_LightClothing"], ItemQuality.Standard), SizeCategory.Small, ItemQuality.Standard, 240.0, 18.0m, true, "wool", ["Market / Clothing / Standard Clothing", "Functions / Worn Items / Headwear"], ["Holdable", "Wear_Hat", "Destroyable_Clothing", "Insulation_Moderate", "Armour_LightClothing"], "Early Modern admission of an exact Medieval clothing definition."),
		new("medieval_eastern_black_riassa", "riassa", "a $colour wool riassa", "This riassa is cut from ample lengths of $colour wool, with a loose body and broad sleeves. The cloth falls in long folds from the shoulders to the lower hem. Plain seams and narrow edge finishing leave the wool's soft, matte surface exposed. Neither the sleeve ends nor the front edges carry contrasting braid, making the broad outline of the robe its principal feature.", SizeCategory.Normal, ItemQuality.Standard, 850.0, 30.0m, true, "wool", ["Market / Clothing / Standard Clothing", "Functions / Worn Items / Bodywear"], ["Holdable", "Variable_Colour", "Wear_Robe", "Destroyable_Clothing", "Insulation_Moderate", "Armour_LightClothing"], "Early Modern admission of an exact Medieval clothing definition."),
		new("medieval_eastern_epimanikia", "epimanikia", "a pair of $colour silk epimanikia", "These $colour silk epimanikia are fitted cuffs made to wrap around the lower sleeves. The silk panels are small but carefully shaped, with ties or narrow bands visible at the inner wrist. Their $colour surface gives a bright, formal finish to the hands and forearms.", SizeCategory.Small, ItemQuality.Good, 80.0, 50.0m, true, "silk", ["Market / Clothing / Luxury Clothing", "Functions / Worn Items / Gloves"], ["Holdable", "Wear_Bracers", "Destroyable_Clothing", "Insulation_Moderate", "Armour_LightClothing", "Variable_FineColour"], "Early Modern admission of an exact Medieval clothing definition."),
		new("medieval_eastern_epitrachelion", "epitrachelion", "a $colour silk epitrachelion", "This $colour silk epitrachelion is a paired stole joined at the neck and falling in two long panels down the front. The $colour silk has a formal sheen, broken by the fold where the fabric sits around the collar. Its length, symmetry, and careful edging make it distinct from an ordinary scarf.", SizeCategory.Small, ItemQuality.Good, 190.0, 70.0m, true, "silk", ["Market / Clothing / Luxury Clothing", "Functions / Worn Items / Bodywear"], ["Holdable", "Wear_Scarf", "Destroyable_Clothing", "Insulation_Moderate", "Armour_LightClothing", "Variable_FineColour"], "Early Modern admission of an exact Medieval clothing definition."),
